pub mod deepq; pub mod export; pub mod milp; pub mod tour; pub mod types;
pub use deepq::{load_weights_file, plan_tour, DeepQPolicy, DeepQWeightsFile, GreedyHeuristicPolicy, NextNodePolicy, TourState, WeightsLoadError};
pub use export::{emit_gcode_stub, ExportOptions}; pub use milp::{pack_select, GreedyPackStub, MilpBackend, PackError, Selection}; pub use tour::{sequence_selection, TourOutcome}; pub use types::{CutEvent, LoopCandidate, PackConstraints, PackInput, PackOutput, PackStrategy};
pub fn run(input:&PackInput)->PackOutput{if input.candidates.is_empty(){return PackOutput{strategy:strategy_label(&input.strategy),solver_status:"infeasible".into(),notes:vec!["no candidates".into()],..Default::default()};}let selection=match pack_select(&input.candidates,&input.constraints,&input.conflict_pairs,&input.strategy){Ok(s)=>s,Err(e)=>return PackOutput{strategy:strategy_label(&input.strategy),solver_status:"error".into(),notes:vec![e.to_string()],..Default::default()}};let tour=sequence_selection(&input.candidates,&selection,&input.constraints,&input.strategy,input.weights_path.as_deref());let selected_loop_ids=selection.selected_indices.iter().map(|&i|input.candidates[i].id.clone()).collect();let tour_order=tour.order_indices.iter().map(|&i|input.candidates[i].id.clone()).collect();let unplaced=selection.unplaced_indices.iter().map(|&i|input.candidates[i].id.clone()).collect();let paths=tour.order_indices.iter().map(|&i|input.candidates[i].points.clone()).collect();let strategy=match input.strategy{PackStrategy::Deepq=>format!("deepq/{}",tour.policy_name),PackStrategy::Milp=>selection.strategy_label.clone(),PackStrategy::Greedy=>"greedy".into()};PackOutput{selected_loop_ids,tour_order,cuts:tour.cuts,strategy,solver_status:tour.solver_status,unplaced,notes:tour.notes,paths}}
fn strategy_label(s:&PackStrategy)->String{match s{PackStrategy::Milp=>"milp-greedy-stub".into(),PackStrategy::Deepq=>"deepq-greedy-fallback".into(),PackStrategy::Greedy=>"greedy".into()}}
